WHO = {'column': [('mulcefeyeben', 277977), ('quchepy', 277977), ('mulceffelsof', 277977), ('quchclysen', 277977), ('thivi', 277977), ('mulcefldmicr', 0), ('psilofchepy', 0), ('mulceffelsof', 0)], 'bridge': [('mueflldmicro', 0), ('brifecfelsof', 280965), ('alphafoldmicro', 280965), ('mueflldmicro', 0), ('alphafoldmicro', 0), ('alphafoldmicro', 287766), ('alphafoldmicro', 290627), ('alphafoldmicro', 0)], 'tree': [('aprilldum', 278233), ('aprilfools', 0), ('alphaffools', 0), ('mueflfldum', 281093), ('uneyeeffools', 281346), ('aprilfools', 0), ('zeeceldum', 282045), ('quhlyeaeli', 0)], 'manor': [('muelldum', 280394), ('aprileben', 0), ('mueflffools', 281794), ('mueflffools', 0), ('mueflfldum', 0), ('mulclysen', 286240), ('mulcefclysen', 0), ('muelldum', 291832)], 'tower': [('quldmeclysen', 0), ('zeecefhepy', 0), ('brifeclysen', 283700), ('brifecfelsof', 285349), ('thizchili', 286240), ('quldmlysen', 287888), ('psilocfchepy', 289676)], 'temple': [('einsof', 282045), ('psilofldum', 283444)], 'castle': [('quldmeclysen', 282745), ('quldmeclysen', 0)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW346(OracleReleaseRuntimeW474):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
